#!/usr/bin/env node
// Writes the main navigation and the footer links (tools/site-nav.mjs) into every hand-written page.
//
//   node tools/build-nav.mjs           # rewrite <nav class="site-nav"> and <p class="site-footer__links"> of every page below
//   node tools/build-nav.mjs --check   # report the pages that are out of date and exit 1, writes nothing
//
// The docs pages are generated by tools/build-docs.mjs, which takes the same navigation from tools/site-nav.mjs.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { siteNav, siteFooterLinks, NAV_PATTERN, FOOTER_PATTERN } from './site-nav.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// Hand-written pages: file, path to the site root, page key for aria-current.
export const HAND_PAGES = [
  ['index.html', '', 'home'],
  ['configurator/index.html', '../', 'configurator'],
  ['roadmap/index.html', '../', 'roadmap'],
  ['changelog/index.html', '../', 'changelog'],
  ['impressum/index.html', '../', 'impressum'],
  ['datenschutz/index.html', '../', 'datenschutz'],
];

export function withNav(html, prefix, current, file) {
  if (!NAV_PATTERN.test(html)) throw new Error(`${file}: <nav class="site-nav"> not found`);
  if (!FOOTER_PATTERN.test(html)) throw new Error(`${file}: <p class="site-footer__links"> not found`);
  return html.replace(NAV_PATTERN, siteNav(prefix, current)).replace(FOOTER_PATTERN, siteFooterLinks(prefix, current));
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const stale = [];
  for (const [file, prefix, current] of HAND_PAGES) {
    const target = path.join(ROOT, file);
    const html = fs.readFileSync(target, 'utf8');
    const next = withNav(html, prefix, current, file);
    if (next === html) continue;
    stale.push(file);
    if (!check) fs.writeFileSync(target, next);
  }
  if (check) {
    if (stale.length) {
      console.log(`navigation or footer links out of date in: ${stale.join(', ')} – run node tools/build-nav.mjs`);
      process.exit(1);
    }
    console.log('navigation and footer links: every hand-written page is up to date');
  } else {
    console.log(stale.length ? `navigation and footer links written into ${stale.join(', ')}` : 'navigation and footer links: nothing to do');
  }
}
